package setup

// Page is entirely offline; it never prepopulates or displays stored secrets.
const Page = `<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Moonraker · Configuration</title><style>
:root{color-scheme:light;--ink:#122c31;--accent:#00786c}*{box-sizing:border-box}body{margin:0;background:#e9eeeb;color:var(--ink);font:16px Georgia,serif}main{max-width:840px;margin:32px auto;padding:24px}header{border-top:6px solid var(--accent);padding:18px 0}small{font:13px monospace;letter-spacing:.08em}h1{font-size:34px;margin:12px 0}p{line-height:1.55}form{background:#fff;border:1px solid #baccc4;padding:24px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}label{display:block;font-weight:bold;font-size:15px}input:not([type=checkbox]){width:100%;margin-top:8px;padding:12px;border:1px solid #99afa5;border-radius:0;font:16px monospace}input:focus{outline:2px solid var(--accent);outline-offset:2px}button{margin-top:24px;padding:15px 20px;background:var(--ink);color:white;border:0;font:16px monospace;cursor:pointer}button:disabled{opacity:.6}#status{min-height:3em}footer{font:13px monospace;line-height:1.5;margin-top:24px}@media(max-width:600px){main{margin:0;padding:18px}.grid{grid-template-columns:1fr}form{padding:18px}h1{font-size:28px}}
</style><main><header><small>MOONRAKER → MQTT / ESP32-S3</small><h1>Connecter le pont.</h1><p>Configuration locale uniquement. Le point d’accès est protégé par WPA2 ; le formulaire utilise HTTP sur ce réseau isolé. Aucun service distant, aucune administration sur le réseau de l’imprimante.</p></header><form id="setup" autocomplete="off"><div class="grid"><label>Réseau Wi-Fi<input name="ssid" type="text" value="" maxlength="32" required autocomplete="off"></label><label>Mot de passe Wi-Fi (vide = réseau ouvert)<input name="wifi_password" type="password" value="" maxlength="63" autocomplete="off"></label><label>Hôte Moonraker (IPv4 ou DNS)<input name="moonraker_host" type="text" value="" maxlength="253" required autocomplete="off"></label><label>Port Moonraker<input name="moonraker_port" type="number" value="7125" maxlength="5" required min="1" max="65535" autocomplete="off"></label><label>Clé API Moonraker (facultative)<input name="api_key" type="password" value="" maxlength="256" autocomplete="off"></label><label>Hôte MQTT (IPv4 ou DNS)<input name="mqtt_host" type="text" value="" maxlength="253" required autocomplete="off"></label><label>Port MQTT<input name="mqtt_port" type="number" value="1883" maxlength="5" required min="1" max="65535" autocomplete="off"></label><label>Utilisateur MQTT (facultatif)<input name="mqtt_username" type="text" value="" maxlength="128" autocomplete="off"></label><label>Mot de passe MQTT<input name="mqtt_password" type="password" value="" maxlength="256" autocomplete="off"></label><label>Identifiant client<input name="client_id" type="text" value="moonraker2mqtt-esp32" maxlength="64" required autocomplete="off"></label><label>Préfixe des topics<input name="topic_prefix" type="text" value="moonraker" maxlength="128" required autocomplete="off"></label><label>Intervalle de lecture (secondes)<input name="poll_seconds" type="number" value="5" maxlength="4" required min="1" max="3600" autocomplete="off"></label></div><p><label><input name="commands" type="checkbox"> Autoriser les commandes MQTT (désactivé par défaut)</label></p><p id="recovery" hidden><strong>Stockage corrompu, version non prise en charge ou générations ambiguës.</strong> La sauvegarde normale est bloquée pour préserver les preuves. Conservez une copie des deux secteurs avant réparation si nécessaire. La réparation efface uniquement les deux secteurs de paramètres [0x1fe000, 0x200000), y compris toute version inconnue ; elle ne peut pas être annulée.<label><input name="repair" type="checkbox"> Je confirme la perte des anciens paramètres et l’effacement des deux secteurs réservés.</label></p><button type="submit">Préparer et redémarrer</button><p id="status" role="status" aria-live="polite"></p></form><footer>La réponse « préparés » ne signifie pas « enregistrés ». La flash est écrite au démarrage suivant, avant la radio. Ne débranchez pas pendant ce redémarrage. Les paramètres restent en clair dans la flash ; TLS n’est pas activé.</footer></main><script>
const f=document.getElementById('setup'),status=document.getElementById('status'),recovery={{RECOVERY}},unavailable={{UNAVAILABLE}},button=f.querySelector('button');document.getElementById('recovery').hidden=!recovery;f.elements.repair.disabled=!recovery;f.elements.repair.required=recovery;if(recovery)button.textContent='Effacer les deux secteurs et redémarrer';if(unavailable){button.disabled=true;status.textContent='Stockage inaccessible : diagnostic nécessaire. Aucun effacement autorisé.'}f.addEventListener('submit',async e=>{e.preventDefault();if(unavailable)return;if(recovery&&(!f.elements.repair.checked||!confirm('Effacer définitivement les DEUX secteurs de paramètres, y compris les versions inconnues, puis enregistrer ce formulaire au redémarrage ?')))return;button.disabled=true;const data=Object.fromEntries(new FormData(f));delete data.repair;data.commands=f.elements.commands.checked;for(const k of ['moonraker_port','mqtt_port','poll_seconds'])data[k]=Number(data[k]);const headers={'Content-Type':'application/json','X-Setup-Token':'{{TOKEN}}'};if(recovery)headers['X-Setup-Repair']='erase-two-settings-slots';try{const r=await fetch(recovery?'/repair':'/settings',{method:'POST',headers,body:JSON.stringify(data)});status.textContent=await r.text();if(r.status!==202)button.disabled=false;else f.reset()}catch(e){status.textContent='Connexion interrompue : vérifiez le port série avant de réessayer.';button.disabled=false}});
</script></html>`
